using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Threading;
namespace Dafeiyu.Tests {public static class ShortcutCaptureUiTests {
static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}static System.Collections.Generic.IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in All<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
[STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{var settings=new PetSettings{OnboardingState="completed",AutoUpdate=false,GreetingEnabled=false};foreach(var key in settings.Hotkeys.Keys.ToArray())settings.Hotkeys[key]="";var pet=new PetWindow(null,settings,new SettingsStore(Path.GetFullPath("work/key-capture/"+Guid.NewGuid().ToString("N")+"/settings.json")),null);pet.Show();var panel=new ShortcutSettingsPanel(pet);var window=new Window{Content=panel,Width=650,Height=650};window.Show();window.UpdateLayout();var field=All<TextBox>(panel).Single(x=>x.Name=="Hotkeynewchat");Check(field.IsReadOnly,"keyboard field cannot accept typed text");string before=settings.LocalShortcuts["newchat"];
var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=delegate{timer.Stop();var dialog=app.Windows.OfType<ShortcutCaptureDialog>().Single();Check(typeof(PetWindow).GetField("hotkeys",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet)==null,"global bindings suspended during capture");dialog.CaptureKey(Key.LeftCtrl,ModifierKeys.Control,false);Check(dialog.Combination==null,"pure modifier not recorded");dialog.CaptureKey(Key.F11,ModifierKeys.Control|ModifierKeys.Shift,false);Check(dialog.Combination=="Ctrl+Shift+F11","physical combination recorded");Check(All<Button>(dialog).Single(x=>x.Name=="AcceptCapturedShortcut").IsDefault,"Enter confirms recorded shortcut through the default button");dialog.CaptureKey(Key.A,ModifierKeys.Control,true);Check(dialog.Combination=="Ctrl+Shift+F11","repeat ignored");All<Button>(dialog).Single(x=>x.Name=="AcceptCapturedShortcut").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};timer.Start();typeof(ShortcutSettingsPanel).GetMethod("Capture",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(panel,new object[]{ShortcutCatalog.All.Single(x=>x.Id=="newchat")});Check(field.Text=="Ctrl+Shift+F11"&&settings.LocalShortcuts["newchat"]==before,"captured combination is reviewable before save");Check(typeof(PetWindow).GetField("hotkeys",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet)!=null,"global bindings restored");All<Button>(panel).Single(x=>x.Name=="SaveShortcutnewchat").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(settings.LocalShortcuts["newchat"]=="Ctrl+Shift+F11","saved captured combination applies");Check(!app.Windows.OfType<ChatWindow>().Any(),"capture does not create conversation");window.Close();pet.Close();app.Shutdown();Console.WriteLine("PASS: "+checks+" native key capture UI checks");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.GetType().FullName+": "+ex.Message);if(ex.InnerException!=null)Console.Error.WriteLine(ex.InnerException.GetType().FullName+": "+ex.InnerException.Message);app.Shutdown();return 1;}}}}
